MONGODB_MANIFEST = """# MongoDB 7 single-node replica set with a persistent volume.
# Generated by DocKube - edit freely, then use Apply Selected YAML.
apiVersion: v1
kind: Secret
metadata:
  name: mongodb-secret
type: Opaque
stringData:
  mongodb-root-password: "rootpassword"
---
apiVersion: v1
kind: Service
metadata:
  name: mongodb
spec:
  clusterIP: None
  selector:
    app: mongodb
  ports:
    - name: mongodb
      port: 27017
      targetPort: 27017
---
apiVersion: apps/v1
kind: StatefulSet
metadata:
  name: mongodb
spec:
  serviceName: mongodb
  replicas: 1
  selector:
    matchLabels:
      app: mongodb
  template:
    metadata:
      labels:
        app: mongodb
    spec:
      containers:
        - name: mongodb
          image: mongo:7
          ports:
            - containerPort: 27017
          command: ["mongod", "--replSet", "rs0", "--bind_ip_all"]
          env:
            - name: MONGO_INITDB_ROOT_USERNAME
              value: root
            - name: MONGO_INITDB_ROOT_PASSWORD
              valueFrom:
                secretKeyRef:
                  name: mongodb-secret
                  key: mongodb-root-password
          volumeMounts:
            - name: data
              mountPath: /data/db
          readinessProbe:
            exec:
              command: ["mongosh", "--quiet", "--eval", "db.adminCommand('ping')"]
            initialDelaySeconds: 25
            periodSeconds: 10
  volumeClaimTemplates:
    - metadata:
        name: data
      spec:
        accessModes: ["ReadWriteOnce"]
        resources:
          requests:
            storage: 1Gi
"""

GITHUB_WORKFLOW = """# GitHub Actions CI/CD pipeline.
# Generated by DocKube - place at .github/workflows/ci-cd.yml
name: CI/CD

on:
  push:
    branches: [main]
  pull_request:
    branches: [main]

env:
  IMAGE_NAME: myapp
  TAG: ${{ github.sha }}

jobs:
  build:
    runs-on: ubuntu-22.04
    steps:
      - uses: actions/checkout@v4
      - name: Set up Python
        uses: actions/setup-python@v5
        with:
          python-version: "3.11"
      - name: Install dependencies
        run: pip install -r requirements.txt
      - name: Lint
        run: python -m compileall -q .
      - name: Build Docker image
        run: docker build -t $IMAGE_NAME:$TAG .
      - name: Log in to GHCR
        uses: docker/login-action@v3
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}
      - name: Push image
        run: docker push ghcr.io/${{ github.repository }}/$IMAGE_NAME:$TAG
      - uses: actions/upload-artifact@v4
        with:
          name: app-image
          path: .

  deploy:
    needs: build
    runs-on: ubuntu-22.04
    if: github.ref == 'refs/heads/main'
    steps:
      - uses: actions/checkout@v4
      - name: Configure kubectl
        uses: azure/setup-kubectl@v4
      - name: Deploy manifests
        run: kubectl apply -f k8s/
      - name: Verify rollout
        run: kubectl rollout status deployment/myapp --timeout=120s
"""

JENKINSFILE = """// Declarative Jenkins pipeline.
// Generated by DocKube - place at the root of your repository.
pipeline {
    agent any

    environment {
        IMAGE_NAME = 'myapp'
        BUILD_TAG  = "${env.BUILD_NUMBER}"
    }

    stages {
        stage('Checkout') {
            steps {
                checkout scm
            }
        }
        stage('Build') {
            steps {
                sh 'docker build -t ${IMAGE_NAME}:${BUILD_TAG} .'
            }
        }
        stage('Test') {
            steps {
                sh 'docker run --rm ${IMAGE_NAME}:${BUILD_TAG} python -m pytest -q'
            }
        }
        stage('Deploy') {
            when { branch 'main' }
            steps {
                sh 'docker push ${IMAGE_NAME}:${BUILD_TAG}'
            }
        }
    }

    post {
        always {
            echo 'Build finished'
        }
        failure {
            echo 'Build failed - check the console output'
        }
    }
}
"""

TERRAFORM_MAIN = """# Terraform starter configuration.
# Generated by DocKube - place at main.tf then run: terraform init
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
  }
}

# A local file stands in for real infrastructure so the plan applies anywhere.
resource "local_file" "demo" {
  filename = "${path.module}/demo.txt"
  content  = "Created by Terraform at ${formatdate("YYYY-MM-DD", timestamp())}\\n"
}

resource "local_sensitive_file" "secret" {
  filename   = "${path.module}/secret.txt"
  content    = var.api_token
  depends_on = [local_file.demo]
}

variable "api_token" {
  description = "Example sensitive input; wire this to a real secret source."
  type        = string
  sensitive   = true
  default     = "replace-me"
}

output "demo_file" {
  value = local_file.demo.filename
}
"""

ANSIBLE_PLAYBOOK = """# Ansible playbook that configures a sample web server.
# Generated by DocKube - run with: ansible-playbook playbook.yml --check
- name: Configure sample web servers
  hosts: webservers
  become: true
  vars:
    http_port: 80

  tasks:
    - name: Update apt cache
      ansible.builtin.apt:
        update_cache: true
      tags: [always]

    - name: Install nginx
      ansible.builtin.apt:
        name: nginx
        state: present
      notify: Restart nginx
      tags: [install]

    - name: Ensure nginx is running
      ansible.builtin.service:
        name: nginx
        state: started
        enabled: true
      tags: [service]

  handlers:
    - name: Restart nginx
      ansible.builtin.service:
        name: nginx
        state: restarted
"""

